python3 -c "
import json
data = json.load(open('/app/resources/treasury_bulletin_2024_12.json'))
pages = data.get('document', {}).get('pages', [])
for i, page in enumerate(pages[:30]):
    elements = page.get('elements', [])
    for el in elements:
        if 'table' in el.get('type', '').lower() or 'federal securities' in str(el).lower():
            print(f'Page {i}: {el.get(\"id\")}, type: {el.get(\"type\")}')"
